import{_ as t,o,c as a,ae as s}from"./chunks/framework.Dn6zxbF8.js";const u=JSON.parse('{"title":"NodeJS files and directories names convention","description":"","frontmatter":{"id":"3122196229","title":"NodeJS files and directories names convention","state":"Approved","created":"2020-11-10T00:00:00.000Z","tags":["nodejs"],"category":"JavaScript"},"headers":[],"relativePath":"adrs/3122196229/README.md","filePath":"adrs/3122196229/README.md"}'),n={name:"adrs/3122196229/README.md"};function i(r,e,c,d,l,h){return o(),a("div",null,[...e[0]||(e[0]=[s('<h1 id="nodejs-files-and-directories-names-convention" tabindex="-1">NodeJS files and directories names convention <a class="header-anchor" href="#nodejs-files-and-directories-names-convention" aria-label="Permalink to &quot;NodeJS files and directories names convention&quot;">​</a></h1><h2 id="context" tabindex="-1">Context <a class="header-anchor" href="#context" aria-label="Permalink to &quot;Context&quot;">​</a></h2><p>Across the ecosystem, we can find all sort of files and directories naming conventions in NodeJS projects.</p><p>That has caused misalignment, shifting the focus away from more important matters, also have created conventions that introduce problems such:</p><ul><li>Disagreement around the English language, making it even more difficult for the non-English speaker to figure out the right decision.</li><li>Case sensitive vs. case insensitive file systems, causing issues in different environments such as your local computer vs. CI/CD computers.</li><li>Format mismatching around separating English words.</li></ul><p>The <code>camelCase</code>, and/or <code>PascalCase</code> for naming convention, although this seems the right solution, there are some caveats.</p><p>What happens for the following cases <code>httpClient.ts</code> vs. <code>HTTPClient.ts</code> vs. <code>HttpClient.ts</code>?</p><ul><li>Which one is the more appropriate choice here without getting into disagreement and use the phrase &quot;it depends&quot;?</li></ul><p>In some cases, the file <code>PascalCase</code> is used if the file is a class or a React component, otherwise follow <code>camelCase</code> is used.</p><ul><li>What happens when the file contains more than a class or a React component? How do we take the appropriate decision about it without getting into disagreement and use the phrase &quot;it depends&quot;?</li></ul><p>Also, does that means that if we refactor the code and we move the React component out of a file, that file name must change?</p><p>That would introduce more potential refactoring like renaming file paths, adding more unnecessary lines of code changes and extra work in code reviews.</p><p>As well as issues in <code>CI</code> environments, where it may be the case that <code>git</code> didn&#39;t rename the file due to case-insensitive file systems, and you must use <code>git mv [old file] [new file]</code> to fix such issue.</p><h2 id="resolution" tabindex="-1">Resolution <a class="header-anchor" href="#resolution" aria-label="Permalink to &quot;Resolution&quot;">​</a></h2><p>File or directory names:</p><ul><li><strong>MUST NOT</strong> contain any leading or trailing spaces</li><li><strong>MUST</strong> be lowercase i.e., no uppercase or mixed case names are allowed</li><li><strong>MUST</strong> separate what constitutes an English word by <code>-</code></li><li><strong>MUST NOT</strong> contain any of the following characters: <code>~)(&#39;!*</code></li><li><strong>MUST NOT</strong> start with <code>.</code> or <code>_</code></li></ul>',16)])])}const p=t(n,[["render",i]]);export{u as __pageData,p as default};
